/**
 * attractions — Destination 内页结构化景点数据（真实地点对象，非字符串高亮）。
 *
 * 数据口径（硬规则）：
 *   · 只收录现实世界地点（temple / museum / market / park / neighbourhood），
 *     禁止把活动/主题（"Rooftop bars at sunset" 类）作为 attraction 本体。
 *   · image 必须是该地点的真实照片（Pexels CDN，已逐张目检主体匹配；
 *     流程见 memory：pexels search → ID → curl 200 验证 → 目检城市正确）。
 *   · lat/lon = 真实公开坐标（WGS84），驱动 Wink search/geo 附近酒店与
 *     Route Builder 地理排序。
 *   · admission = 事实性准入状态（Paid admission / Free entry），不编造票价数字。
 *   · viatorQuery = Viator /products/search 的 attraction 级搜索词。
 *
 * 覆盖策略：先做 Bangkok（Wink + Viator 供给已验证）；其余城市无记录时
 * Destination 页回退到既有 highlights 字符串渲染（行为不变）。记录按城市
 * 增量补充，组件零改动（数据驱动，155 → 1000+ 城可扩展）。
 */

import { ATTRACTIONS_WAVE2 } from "./attractions-wave2";

export interface AttractionRecord {
  /** 稳定 id（slug 化）。 */
  id: string;
  /** 现实世界地点名。 */
  name: string;
  /** 一句话事实描述。 */
  description: string;
  /** 该地点真实照片 URL（next.config 白名单 CDN）。 */
  image: string;
  /** 图片 alt（描述照片主体）。 */
  imageAlt: string;
  /** 真实坐标（WGS84 度）。 */
  lat: number;
  lon: number;
  /** 地点类型。 */
  type:
    | "Historic site"
    | "Temple"
    | "Market"
    | "Neighbourhood"
    | "Park"
    | "Museum"
    | "Landmark"
    | "Viewpoint"
    // wave2 补录景点使用的补充标签（真实类别，非新 feature）
    | "Beach"
    | "Nature reserve"
    | "Square"
    | "Street";
  /** 准入状态（事实性，无票价数字；无法可靠验证 → 缺省不写）。 */
  admission?: "Paid admission" | "Free entry";
  /** Viator attraction 级产品搜索词（无合适产品 → null，页面诚实空态）。 */
  viatorQuery: string | null;
  /** 坐标/地点事实来源（如 "wikidata"、"osm"、"official site"）。 */
  source: string;
  /** 人工核验日期（ISO；含图片主体目检）。 */
  verifiedAt: string;
}

