/** 合并视图：既有 129 城 + wave2 新增 50 城。消费端（getAttractions /
 *  findAttractionByName / 页面）接口不变，新增城市自动生效。 */
export const ATTRACTIONS: Record<string, AttractionRecord[]> = {
  ...ATTRACTIONS_CORE,
  ...ATTRACTIONS_WAVE2,
};


/** 取某城市的结构化景点（无记录 → 空数组，调用方回退既有 highlights 渲染）。 */
export function getAttractions(slug: string): AttractionRecord[] {
  return ATTRACTIONS[slug] ?? [];
}

/** 按名称匹配结构化景点（Route Builder 用；未匹配 → undefined）。 */
export function findAttractionByName(
  slug: string,
  name: string,
): AttractionRecord | undefined {
  const q = name.trim().toLowerCase();
  return ATTRACTIONS[slug]?.find((a) => a.name.trim().toLowerCase() === q);
}
